// Extract AfterShip payload and filter to key statuses only
const body = $input.first().json.body || $input.first().json;
const msg = body.msg || {};
const tag = msg.tag || '';

// Only send updates for these statuses
const KEY_STATUSES = ['InTransit', 'OutForDelivery', 'Delivered', 'AttemptFail', 'Exception', 'AvailableForPickup'];

if (!KEY_STATUSES.includes(tag)) {
  // Not a key status — stop processing silently
  return [];
}

const trackingNumber = (msg.tracking_number || '').toString().trim();
if (!trackingNumber) return [];

const checkpoint = msg.last_checkpoint || {};
const eta = msg.estimated_delivery_date?.datetime || '';

return [{
  json: {
    tracking_number: trackingNumber,
    tag: tag,
    last_message: checkpoint.message || '',
    last_location: checkpoint.location || '',
    last_time: checkpoint.checkpoint_time || '',
    eta: eta
  }
}];

// Extract customer phone from Monday result
const data = $input.first().json.data || {};
const items = data.items_page_by_column_values?.items || [];

if (!items.length) return []; // Order not found

const item = items[0];
const phoneCol = (item.column_values || []).filter(c => c.id === 'phone__1')[0];
const rawPhone = phoneCol?.text || '';

// Normalize phone: strip everything except digits
const phone = rawPhone.replace(/[^0-9]/g, '');
if (!phone) return []; // No phone on record

// Get tracking context from previous node
const tracking = $('Extract & Filter').first().json;

return [{
  json: {
    phone: phone,
    customer_name: item.name,
    tracking_number: tracking.tracking_number,
    tag: tracking.tag,
    last_message: tracking.last_message,
    last_location: tracking.last_location,
    eta: tracking.eta
  }
}];

// Format a clear Hebrew WhatsApp message
const { tag, last_message, last_location, eta, phone, tracking_number } = $input.first().json;

const statusMap = {
  InTransit: 'בדרך אליך 🚚',
  OutForDelivery: 'יוצא למשלוח עכשיו 📦',
  Delivered: 'נמסר בהצלחה ✅',
  AttemptFail: 'ניסיון מסירה נכשל - יצרו קשר עם השליח ⚠️',
  Exception: 'בעיה בתהליך המשלוח ⚠️',
  AvailableForPickup: 'ממתין לאיסוף בנקודת חלוקה 📍'
};

const statusHebrew = statusMap[tag] || tag;

// Format ETA nicely
let etaLine = '';
if (eta) {
  try {
    const d = new Date(eta);
    const formatted = d.toLocaleDateString('he-IL', {
      weekday: 'long',
      day: 'numeric',
      month: 'long'
    });
    etaLine = `\nצפי הגעה: ${formatted}`;
  } catch(e) {
    etaLine = `\nצפי הגעה: ${eta}`;
  }
}

const locationLine = last_location ? `\nמיקום נוכחי: ${last_location}` : '';

const message = `*OneZone - עדכון משלוח* 🏆\n\nסטטוס: ${statusHebrew}${locationLine}${etaLine}\n\nמס' מעקב: ${tracking_number}\n\nלמעקב מפורט: https://t.17track.net/he#nums=${tracking_number}`;

return [{ json: { phone, message } }];
